:root {
  color-scheme: dark;
  font-family: "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
  background: #171334;
  color: #f8f4ff;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background:
    radial-gradient(circle at 15% 15%, rgba(255, 205, 112, 0.18), transparent 26rem),
    radial-gradient(circle at 85% 80%, rgba(126, 116, 255, 0.3), transparent 30rem),
    linear-gradient(160deg, #1e1944 0%, #12102a 55%, #090818 100%);
}

.game {
  width: min(100%, 560px);
}

.castle-card {
  position: relative;
  overflow: hidden;
  padding: clamp(28px, 6vw, 52px);
  text-align: center;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(48, 42, 104, 0.92), rgba(24, 20, 56, 0.96));
  box-shadow:
    0 30px 70px rgba(0, 0, 0, 0.45),
    inset 0 1px 0 rgba(255, 255, 255, 0.14);
}

.castle-card::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(rgba(255, 255, 255, 0.5) 1px, transparent 1px);
  background-size: 46px 46px;
  opacity: 0.22;
}

.eyebrow {
  margin: 0 0 10px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: #ffd27a;
}

h1 {
  margin: 0;
  font-size: clamp(1.85rem, 6vw, 2.8rem);
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.castle {
  position: relative;
  z-index: 1;
  display: block;
  width: min(78%, 320px);
  margin: 18px auto 8px;
  filter: drop-shadow(0 16px 22px rgba(0, 0, 0, 0.4));
}

.score-label {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: #b8afff;
}

.score {
  margin: 4px 0 18px;
  font-size: clamp(3.5rem, 16vw, 5.5rem);
  font-weight: 800;
  line-height: 1;
  color: #ffd27a;
  text-shadow: 0 0 32px rgba(255, 210, 122, 0.4);
  font-variant-numeric: tabular-nums;
}

.add-point {
  position: relative;
  z-index: 1;
  width: min(100%, 300px);
  padding: 16px 28px;
  border: 0;
  border-radius: 999px;
  font: inherit;
  font-size: 1.08rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #241a03;
  cursor: pointer;
  background: linear-gradient(180deg, #ffe3a1, #ffbf4d);
  box-shadow:
    0 10px 0 #b97718,
    0 18px 30px rgba(0, 0, 0, 0.35);
  transition: transform 120ms ease, box-shadow 120ms ease;
}

.add-point:hover {
  transform: translateY(-2px);
  box-shadow:
    0 12px 0 #b97718,
    0 22px 34px rgba(0, 0, 0, 0.38);
}

.add-point:active {
  transform: translateY(6px);
  box-shadow:
    0 4px 0 #b97718,
    0 8px 16px rgba(0, 0, 0, 0.3);
}

.add-point:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 4px;
}

.add-point.pop {
  animation: pop 220ms ease-out;
}

.hint {
  position: relative;
  z-index: 1;
  margin: 22px 0 0;
  font-size: 0.9rem;
  color: #bdb7e8;
}

@keyframes pop {
  50% {
    transform: translateY(4px) scale(0.97);
  }
}

@media (prefers-reduced-motion: reduce) {
  .add-point {
    transition: none;
  }

  .add-point.pop {
    animation: none;
  }
}
